//! The global styles functions; every expected value (and WordPress's object cache keys) was produced by WordPress;
//! the values WordPress 7.2 changed are 7.2-RC2's.
//!
//! Generated by `.superpowers/gen_global_styles.py`; edit the generator, not the cases.

#![allow(unused_variables)]

mod support;

use std::rc::Rc;

use speedyspec_hooks::Value;
use speedyspec_wp_theme_json::global_styles::{GlobalStylesApi, ResolverGlobalSettings};
use speedyspec_wp_theme_json::resolver::{ResolverDeps, ThemeJsonResolver};
use speedyspec_wp_theme_json::{
    MemoryActiveTheme, MemoryBlockMetadata, MemoryGlobalStylesPosts, MemoryVariationRegistrar,
    MemoryWpCache, NoLayerFilters, NoTranslation, RecordedDiagnostics, ThemeJsonApi, ThemeJsonDeps,
};
use support::core_blocks::core_blocks;
use support::{AsciiText, assert_php_same as assert_php_eq, json, php_list, safe_css, st};

fn dir() -> String {
    format!("{}/tests/data/themedir1", env!("CARGO_MANIFEST_DIR"))
}

struct Harness {
    posts: Rc<MemoryGlobalStylesPosts>,
    notices: Rc<RecordedDiagnostics>,
    cache: Rc<MemoryWpCache>,
    styles: Rc<GlobalStylesApi>,
}

impl Harness {
    fn new(
        theme_dir: &str,
        template_dir: Option<&str>,
        classic: Value,
        development: bool,
    ) -> Harness {
        let blocks = Rc::new(MemoryBlockMetadata::new());
        for b in core_blocks() {
            blocks.register(b);
        }
        for (block, style) in [("core/group", "section-a"), ("core/quote", "fancy")] {
            blocks.register_style(
                block,
                json(&format!(r#"{{"name":"{style}","label":"{style}"}}"#)),
            );
        }
        let notices = Rc::new(RecordedDiagnostics::default());
        let global = Rc::new(ResolverGlobalSettings::default());
        let deps = ThemeJsonDeps::new(
            blocks.clone(),
            Rc::new(AsciiText),
            Rc::new(NoTranslation),
            notices.clone(),
            safe_css(),
        )
        .with_global_settings(global.clone());
        let api = Rc::new(ThemeJsonApi::new(deps));
        let mut theme = MemoryActiveTheme::new(theme_dir, template_dir);
        theme.development_mode = development;
        *theme.classic_settings.borrow_mut() = classic;
        let posts = Rc::new(MemoryGlobalStylesPosts::default());
        let resolver = Rc::new(ThemeJsonResolver::new(
            api,
            ResolverDeps {
                theme: Rc::new(theme),
                filters: Rc::new(NoLayerFilters),
                posts: posts.clone(),
                registrar: Rc::new(MemoryVariationRegistrar(blocks.clone())),
                core_dir: format!("{}/tests/data/core", env!("CARGO_MANIFEST_DIR")),
            },
        ));
        let cache = Rc::new(MemoryWpCache::default());
        let styles = Rc::new(GlobalStylesApi::new(resolver, cache.clone()));
        global.bind(&styles);
        Harness {
            posts,
            notices,
            cache,
            styles,
        }
    }
    fn cache_keys(&self) -> Value {
        php_list(
            self.cache
                .entries
                .borrow()
                .iter()
                .filter(|(g, _, _)| g == "theme_json")
                .map(|(_, k, _)| Value::Str(k.clone()))
                .collect(),
        )
    }
    fn notices(&self) -> Vec<String> {
        self.notices.notices.borrow().clone()
    }
}

fn triple(data: Value, cache: Value, notices: Vec<String>) -> Value {
    php_list(vec![
        data,
        cache,
        php_list(notices.into_iter().map(Value::Str).collect()),
    ])
}

