#[test]
fn template_parts_classic() {
    let actual = {
        let h = Harness::new(
            &format!("{}/classic", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
            false,
        );
        let g = &h.styles;
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            php_list(vec![
                g.get_theme_data_template_parts().unwrap(),
                g.get_theme_data_custom_templates().unwrap(),
                g.get_theme_directory_pattern_slugs().unwrap(),
            ])
        };
        triple(v, h.cache_keys(), h.notices())
    };
    assert_php_eq(
        &actual,
        &json(r##"[[[],[],[]],["wp_get_theme_data_template_parts"],[]]"##),
    );
}

#[test]
fn development_mode_skips_cache() {
    let actual = {
        let h = Harness::new(
            &format!("{}/block-theme", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
            true,
        );
        let g = &h.styles;
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            php_list(vec![
                Value::Int(
                    g.get_global_stylesheet(&Value::Array(Vec::new()))
                        .unwrap()
                        .len() as i64,
                ),
                Value::Int(
                    match g
                        .get_global_settings(&Value::Array(Vec::new()), &Value::Array(Vec::new()))
                        .unwrap()
                    {
                        Value::Array(e) => e.len() as i64,
                        _ => -1,
                    },
                ),
                Value::Int(match g.get_theme_data_template_parts().unwrap() {
                    Value::Array(e) => e.len() as i64,
                    _ => -1,
                }),
            ])
        };
        triple(v, h.cache_keys(), h.notices())
    };
    assert_php_eq(&actual, &json(r##"[[12824,10,1],[],[]]"##));
}

#[test]
fn saving_user_styles_then_cleaning_cache_shows_new_styles() {
    let actual = {
        let h = Harness::new(
            &format!("{}/block-theme", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
            false,
        );
        let g = &h.styles;
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            let a = g.get_global_stylesheet(&Value::Array(Vec::new())).unwrap();
            h.posts.add("block-theme", r##"{"version":3,"isGlobalStylesUserThemeJSON":true,"styles":{"color":{"background":"#abcdef"}}}"##, "publish");
            let b = g.get_global_stylesheet(&Value::Array(Vec::new())).unwrap();
            g.clean_theme_json_cache();
            let c = String::from_utf8(g.get_global_stylesheet(&Value::Array(Vec::new())).unwrap())
                .unwrap();
            php_list(vec![
                Value::Bool(a == b),
                Value::Bool(c.contains("#abcdef")),
                Value::Int(1),
            ])
        };
        triple(v, h.cache_keys(), h.notices())
    };
    assert_php_eq(
        &actual,
        &json(r##"[[true,true,1],["wp_get_global_stylesheet"],[]]"##),
    );
}

